// Validation for users.appearance. Ids must match client/src/appearance.js (PRESETS, SIZES)
// and client/src/fonts.generated.js (FONTS, generated by tools/gen-fonts.js).
const PRESETS = ["green", "navy", "lavender", "pink", "olive", "graphite", "custom"];
const FONTS = [
  "ibm-plex-sans-thai", "chakra-petch", "sarabun", "noto-sans-thai", "anuphan", "prompt", "kanit",
  "mitr", "bai-jamjuree", "k2d", "noto-serif-thai", "mali", "itim",
];
const SIZES = ["s", "m", "l"];
const TOKENS = ["desk", "paper", "surface", "ink", "title", "highlight"];
const HEX = /^#[0-9a-f]{6}$/i;
const KEYS = ["preset", "light", "dark", "fontDisplay", "fontBody", "size"];

const isPlain = (o) => o !== null && typeof o === "object" && !Array.isArray(o);

function colors(c, name) {
  if (!isPlain(c)) return [null, `${name} must be an object`];
  const keys = Object.keys(c);
  if (keys.length !== TOKENS.length || !TOKENS.every((k) => keys.includes(k))) {
    return [null, `${name} needs exactly: ${TOKENS.join(", ")}`];
  }
  if (!TOKENS.every((k) => typeof c[k] === "string" && HEX.test(c[k]))) return [null, `${name} colors must be #rrggbb`];
  return [Object.fromEntries(TOKENS.map((k) => [k, c[k].toLowerCase()])), null];
}

/** @returns {{ value?: object, error?: string }} */
function validateAppearance(a) {
  if (!isPlain(a)) return { error: "appearance must be an object" };
  const extra = Object.keys(a).filter((k) => !KEYS.includes(k));
  if (extra.length) return { error: `unknown field: ${extra[0]}` };
  const out = {};
  if (a.preset !== undefined) {
    if (!PRESETS.includes(a.preset)) return { error: "unknown preset" };
    out.preset = a.preset;
  }
  if (out.preset === "custom") {
    for (const mode of ["light", "dark"]) {
      const [c, err] = colors(a[mode], mode);
      if (err) return { error: err };
      out[mode] = c;
    }
  } else if (a.light !== undefined || a.dark !== undefined) {
    return { error: "light/dark colors are only allowed with preset \"custom\"" };
  }
  for (const role of ["fontDisplay", "fontBody"]) {
    if (a[role] === undefined) continue;
    if (!FONTS.includes(a[role])) return { error: `unknown font for ${role}` };
    out[role] = a[role];
  }
  if (a.size !== undefined) {
    if (!SIZES.includes(a.size)) return { error: "size must be s, m or l" };
    out.size = a.size;
  }
  return { value: out };
}

module.exports = { validateAppearance, FONTS, PRESETS };
